// Material data as stored in data/materials/*.json (generated by scripts/import_materials.py).

export interface Source {
  citation: string;
  doi: string | null;
  otherDois?: string[];
  notes?: string | null;
  url: string;
  file: string;
  conditions?: string;
  retrieved: string;
}

/** refractiveindex.info formula types: sellmeier1 = "formula 1", sellmeier2 = "formula 2", gases = "formula 6". */
export type Dispersion =
  | { model: 'sellmeier1' | 'sellmeier2' | 'gases'; coefficients: number[]; range: [number, number]; source: Source }
  | { model: 'tabulated'; table: [number, number][]; range: [number, number]; source: Source };

export type MaterialData =
  | { id: string; name: string; kind: 'isotropic'; n: Dispersion }
  | { id: string; name: string; kind: 'uniaxial'; ordinary: Dispersion; extraordinary: Dispersion };

/** A user-entered constant (non-dispersive) index, stored in the project. */
export interface CustomMaterial {
  id: string; // always starts with "custom:"
  name: string;
  n: number;
  k: number; // extinction coefficient, ≥ 0
}

export type Axis = 'x' | 'y' | 'z';

export interface IndexValue {
  n: number;
  k: number;
  /** False if λ is outside the source's published range (value extrapolated or clamped). */
  inRange: boolean;
  range?: [number, number];
}
